params.command:
$ErrorActionPreference='Stop'
$relay=Join-Path $HOME 'HeavenBridgeRepo'
$root=Join-Path $HOME 'HeavenBridgeValidation'
New-Item -ItemType Directory -Force -Path $root | Out-Null
$tmp=Join-Path $root ('uia-' + [guid]::NewGuid().ToString('N'))
$url=(git -C $relay remote get-url origin).Trim()
try {
  git clone --quiet --single-branch --branch agent/bridge-uia-native-20260929 $url $tmp
  if($LASTEXITCODE -ne 0){ throw 'clone failed' }
  Push-Location $tmp
  try {
    Write-Output ('HEAD='+(git rev-parse HEAD).Trim())
    python -m py_compile heaven-bridge/worker.py heaven-bridge/test_worker.py heaven-bridge/tests/test_worker.py
    if($LASTEXITCODE -ne 0){ throw 'py_compile failed' }
    python -m unittest -v heaven-bridge/test_worker.py
    if($LASTEXITCODE -ne 0){ throw 'primary tests failed' }
    python -m unittest -v heaven-bridge/tests/test_worker.py
    if($LASTEXITCODE -ne 0){ throw 'compat tests failed' }
    foreach($script in @('heaven-bridge/bootstrap.ps1','heaven-bridge/manage.ps1','heaven-bridge/uia-helper.ps1')){
      $tokens=$null; $errors=$null
      [void][System.Management.Automation.Language.Parser]::ParseFile((Resolve-Path $script),[ref]$tokens,[ref]$errors)
      if($errors.Count -gt 0){ $errors | Format-List | Out-String | Write-Output; throw ('parse failed '+$script) }
      Write-Output ('PARSE_OK='+$script)
    }
    git diff --check
    if($LASTEXITCODE -ne 0){ throw 'git diff --check failed' }
    Write-Output 'UIA_BRANCH_GATE_OK'
  } finally { Pop-Location }
} finally {
  if(Test-Path $tmp){ Remove-Item -LiteralPath $tmp -Recurse -Force -ErrorAction SilentlyContinue }
}
